	check("diff_max", typeof(d120) == TYPE_FLOAT and absf(d120 - 1.0) < 0.01, "Oltre 60 secondi get_difficulty_factor() non deve superare 1.0")

	basket.set("game_time", 0.0)
	await wait_frames(10)
	var gt = get_prop(basket, "game_time", 0.0)
	check("gt_advances", gt > 0.05, "game_time deve aumentare durante lo stato PLAYING sommando delta")

	basket.set("game_time", 0.0)
